-- Queer Atlas: exactly four researched Gaborone hotels.
-- Researched 2026-08-28. Run after city-batch-gaborone-v1.sql.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
 select * from jsonb_to_recordset($qa_hotels$
[
 {"name":"Avani Gaborone Resort & Casino","aliases":"Avani Gaborone Resort & Casino|Avani Gaborone|Gaborone Sun","city":"gaborone","description":"A palm-ringed city resort with a courtyard pool, spa, sports courts, casino and large social rooms—and the strongest locally specific inclusion signal in this hotel set as host and official venue partner of Botswana's inaugural Pride Awards.","vibe":"social resort scale with a genuine local Pride connection","tags":"social,luxury,relax","hours":"Reception operates 24 hours. Check-in 14:00. The official page currently conflicts on checkout: its header states 10:00 while its FAQ states 11:00; confirm the binding time on the reservation. Restaurants, casino, pool and spa use separate schedules.","link":"https://www.avanihotels.com/en/gaborone","location":"Chuma Drive, Gaborone, Botswana","lat":-24.6513823550,"lng":25.9293281025,"arrival":"Use the official airport transfer or a known taxi, confirm the checkout discrepancy in writing, and request preferred bedding and any accessibility needs before arrival.","best":"Best for LGBTQ+ travellers wanting full resort facilities and a hotel with documented, local queer-community event experience.","crowd":"LGBTQ+ guests mix with Pride organisers, conference delegates, casino visitors, business travellers, sports groups and leisure guests.","dress":"Resort casual by day; polished casual for casino, awards or evening dining.","inclusion":"Avani hosted the completed 2025 BW Pride Awards and was publicly thanked for supporting the LGBTQIA+ ceremony; that is direct local evidence, not a generic chain inference.","basis":"Completed local Pride event evidence plus current first-party property, contact, GPS and arrival information.","class":"Four-star city resort and casino","coords":"Exact GPS published by Avani; checked 2026-08-28.","hours_source":"https://www.avanihotels.com/en/gaborone","safety":"The resort provides a staffed base, but casino and event crowds still require normal drink awareness. Use hotel-arranged transport and confirm who may access the room before inviting a new contact.","sources":["https://www.avanihotels.com/en/gaborone","https://www.avanihotels.com/en/gaborone/contact","https://www.thegazette.news/wp-content/uploads/2025/11/19-NOV-25.pdf"]},
 {"name":"Hilton Garden Inn Gaborone","aliases":"Hilton Garden Inn Gaborone|Hilton Garden Inn","city":"gaborone","description":"A clean-lined CBD hotel beside government and corporate offices, with a pool, secure parking and an uncomplicated international-service base close to the city's late venues.","vibe":"reliable modern CBD comfort with secure practical edges","tags":"mixed,social,relax","hours":"Reception operates 24 hours. Check-in 15:00; check-out 11:00. Restaurant, bar, pool, gym and shuttle use separate schedules.","link":"https://www.hilton.com/en/hotels/gbegigi-hilton-garden-inn-gaborone/","location":"Plot 54366, Western Commercial Road, New CBD, Gaborone, Botswana","lat":-24.64838,"lng":25.90441,"arrival":"Arrange the airport journey in advance because the current property page does not list an airport shuttle; confirm same-bed setup, visitor policy and accessible room directly.","best":"Best for a queer solo traveller or couple wanting predictable service, secured parking and a short ride from CBD nightlife.","crowd":"LGBTQ+ travellers mix with government, SADC, diplomatic, corporate and international leisure guests.","dress":"Contemporary business-casual.","inclusion":"Hilton publishes an explicit LGBTQ+ Pride welcome and inclusive-travel programme across its hotels; local discretion and advance requests remain sensible.","basis":"Current official property policy and hours, Botswana Tourism operating status and coordinates, plus Hilton's direct LGBTQ+ welcome framework.","class":"Four-star Hilton Garden Inn city hotel","coords":"Exact coordinates and operating status published by Botswana Tourism Organisation; checked 2026-08-28.","hours_source":"https://www.hilton.com/en/hotels/gbegigi-hilton-garden-inn-gaborone/","safety":"The staffed CBD property and secured parking help, but the office district quietens late. Use a car door to door and meet new contacts first in the public lobby or restaurant.","sources":["https://www.hilton.com/en/hotels/gbegigi-hilton-garden-inn-gaborone/","https://botswanatourism.co.bw/stay/hilton-garden-inn-gaborone","https://www.hilton.com/en/p/lgbtq-pride/"]},
 {"name":"Protea Hotel by Marriott Gaborone Masa Square","aliases":"Protea Hotel by Marriott Gaborone Masa Square|Protea Hotel Gaborone Masa Square|Masa Square Hotel","city":"gaborone","description":"A central Masa Square hotel with a rooftop pool and gin bar, contemporary African detail and the useful advantage of placing dining, cinema and CBD offices inside the same urban complex.","vibe":"rooftop CBD hotel balancing business polish and social evenings","tags":"social,luxury,cultural","hours":"Reception operates 24 hours. Check-in 15:00; check-out 11:00. Restaurants, rooftop pool, gym and airport shuttle follow separate schedules; current renovations continue until December 2026.","link":"https://www.marriott.com/en-us/hotels/gbepg-protea-hotel-gaborone-masa-square/overview/","location":"Masa Square, New CBD, corner of 1st and Western Commercial Avenue, Gaborone, Botswana","lat":-24.6523693349,"lng":25.9036910534,"arrival":"Reserve the complimentary airport shuttle, ask which floors are affected by the current works, and confirm bedding, sound sensitivity and accessible route before arrival.","best":"Best for LGBTQ+ visitors wanting a central international-chain base with a rooftop social option and several facilities under one roof.","crowd":"LGBTQ+ travellers mix with business guests, conference groups, restaurant visitors, long-stay residents and regional city breakers.","dress":"Smart-casual from breakfast to rooftop drinks.","inclusion":"Marriott's current Welcome All framework and global LGBTQ+ advocacy apply; this does not replace a direct conversation about local room-sharing or visitor needs.","basis":"Current first-party property, hours, renovation and accessibility details paired with Marriott's published inclusion framework and specialist Gaborone inclusion listing.","class":"Four-star Protea by Marriott city hotel","coords":"Exact property coordinate checked against current Botswana accommodation data on 2026-08-28.","hours_source":"https://www.marriott.com/en-us/hotels/gbepg-protea-hotel-gaborone-masa-square/overview/","safety":"Renovation areas and busy shared facilities merit ordinary awareness. Use the staffed lobby for first meetings and the hotel's reserved shuttle or a known driver after late nightlife.","sources":["https://www.marriott.com/en-us/hotels/gbepg-protea-hotel-gaborone-masa-square/overview/","https://help.marriott.com/s/article/marriott-diversity-inclusion","https://www.gaylidays.com/region/gaborone/"]},
 {"name":"Grand Aria Hotel and Conference Centre","aliases":"Grand Aria Hotel and Conference Centre|The Grand Aria Hotel and Conference Centre|Grand Aria Hotels and Conference Centre|Grand Aria Hotel","city":"gaborone","description":"A compact Phase 2 hotel with only a few dozen rooms, a pool and conference spaces, offering a calmer locally run alternative to the CBD towers while remaining close enough for a short drive into the centre.","vibe":"small-scale local hotel with poolside conference ease","tags":"cozy,mixed,relax","hours":"Reception operates 24 hours. Check-in 15:00; check-out 11:00. Restaurant, pool, conference service and breakfast use separate schedules.","link":"https://grandaria.co.bw/","location":"Plot 32943, Phase 2, Gaborone, Botswana","lat":-24.6372,"lng":25.8943,"arrival":"Confirm transport because the property is not on the core nightlife doorstep; request preferred bedding, visitor rules and any step-free room directly.","best":"Best for queer travellers who prefer a smaller property, quieter nights and pool access over a large international business hotel.","crowd":"LGBTQ+ guests mix with local conference groups, families, wedding parties, business visitors and independent travellers.","dress":"Relaxed hotel casual; smarter for functions.","inclusion":"Grand Aria is included in a current LGBTQ-welcoming Gaborone hotel index; there is no claim of queer ownership or dedicated Pride programming.","basis":"Current specialist Gaborone inclusion signal, active first-party property and current third-party operational details with exact arrival times and coordinates.","class":"Three-star independent hotel and conference centre","coords":"Coordinates published in a current property record updated 2026-03-29; checked 2026-08-28.","hours_source":"https://impt.io/hotels/botswana/gaborone/the-grand-aria-hotel-and-conference-centre/","safety":"A smaller hotel can offer discretion, but do not assume staff training from a directory label. Confirm room sharing and visitor policy in advance and use direct evening transport.","sources":["https://grandaria.co.bw/","https://www.gaylidays.com/region/gaborone/","https://impt.io/hotels/botswana/gaborone/the-grand-aria-hotel-and-conference-centre/"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,hours_source text,safety text,sources jsonb)
), hotels as (
 select h.*,string_to_array(h.tags,',')::text[] approved_tags,jsonb_build_object('queue_wait',arrival,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',inclusion,'inclusion_basis',basis,'hotel_class',class,'coordinate_source',coords,'hours_source_url',hours_source,'hours_checked_at','2026-08-28','safety_note',safety,'source_urls',sources,'research_status','individual_current_inclusion_and_official_property_sources','updated_at','2026-08-28T00:00:00Z') intel from raw_hotels h
), updated as (
 update public.places p set name=h.name,type='hotel',description=h.description,vibe=h.vibe,vibe_tags=h.approved_tags,hours=h.hours,link=h.link,location=h.location,lat=h.lat,lng=h.lng,venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from hotels h where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name) returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at)
select h.name,h.city,'hotel',h.description,h.vibe,h.approved_tags,h.hours,h.link,h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now()) from hotels h where not exists(select 1 from public.places p where lower(trim(p.city))=h.city and lower(trim(p.name)) in(select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name));

select public.qa_refresh_city_seo_status('gaborone') where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select lower(trim(city)) city,count(*) filter(where type='hotel') hotel_count,count(*) filter(where type='hotel')=4 target_exactly_four
from public.places
where lower(trim(city))='gaborone' and lower(trim(name)) in('avani gaborone resort & casino','hilton garden inn gaborone','protea hotel by marriott gaborone masa square','grand aria hotel and conference centre')
group by lower(trim(city));

select name,hours,venue_intel->>'inclusion_basis' inclusion_basis,venue_intel->>'hours_source_url' hours_source
from public.places
where lower(trim(city))='gaborone' and type='hotel'
order by name;
